  hs_handshake: 0x00,
  // login (serverbound)
  lo_hello: 0x00,
  lo_ack: 0x03,
  // login (clientbound)
  li_disconnect: 0x00,
  li_encryption_request: 0x01,
  li_login_success: 0x02,
  li_set_compression: 0x03,
  // configuration (serverbound)
  cs_client_info: 0x00,
  cs_finish: 0x03,
  cs_keepalive: 0x04,
  cs_pong: 0x05,
  cs_known_packs: 0x07,
