    w.string("en_US"); // Locale
    w.byte(8); // View distance
    w.varint(0); // Chat mode: enabled
    w.byte(0); // Chat colors: false
    w.byte(0x7f); // Displayed skin parts
    w.varint(1); // Main hand: right
